def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * N for _ in range(N)]

    # Populate the table with the given grid values
    for value in grid_values:
        x, y, val = value
        dp[x][y] = val

    # Fill in the table with the maximum sum of values
    # collected on two paths from the top-left corner
    # to the bottom-right corner
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Return the maximum sum of values collected on two paths
    return dp[N - 1][N - 1]
