def find_most_unhappy_day(schedule):
    total_hours = 0
    max_unhappiness = 0
    most_unhappy_day = 1
    for i in range(1, 8):
        hours_in_school = schedule[i - 1][0]
        hours_in_extra_classes = schedule[i - 1][1]
        total_hours = hours_in_school + hours_in_extra_classes
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = i
    if max_unhappiness == 0:
        return 0
    else:
        return most_unhappy_day
