def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    for month, budget in enumerate(budgets, start=1):
        remaining = 300 - budget
        if remaining >= 100:
            savings = remaining // 100 * 100
            total_savings += savings
        else:
            return -month
    return total_savings * 1.2
