def minimum_students_to_leave(heights):
    # Find the peek index
    peek_index = heights.index(max(heights))

    # Count the number of students that need to leave
    count = 0
    for i in range(peek_index):
        if heights[i] > heights[peek_index]:
            count += 1

    return count

